  const canteiro2 = SZGame2D.createSprite({ x: 272, y: 250, w: 96, h: 96, image: "canteiro" });
  const canteiro3 = SZGame2D.createSprite({ x: 424, y: 250, w: 96, h: 96, image: "canteiro" });
