    escolhido = 2;
  }, "nuvens_quadro_1_events_1");
  SZGame2D.onKey("3", () => {
    escolhido = 3;
  }, "nuvens_quadro_1_events_2");
  SZGame2D.onKey("Space", () => {

  }, "nuvens_quadro_1_events_3");
  SZGame2D.onKey("Enter", () => {

  }, "nuvens_quadro_1_events_4");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    if (plantado1) {
      SZGame2D.setImage(canteiro1, "muda");
    } else {
      SZGame2D.setImage(canteiro1, "canteiro");
    }
    if (plantado2) {
      SZGame2D.setImage(canteiro2, "muda");
    } else {
      SZGame2D.setImage(canteiro2, "canteiro");
    }
    if (plantado3) {
      SZGame2D.setImage(canteiro3, "muda");
    } else {
      SZGame2D.setImage(canteiro3, "canteiro");
    }
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "jardim");
    SZGame2D.drawLabel(ctx, "Plantar com moedas", 18, 32, "#3b2f6b", 24, "left");
    SZGame2D.drawLabel(ctx, "1, 2 e 3 escolhem o canteiro. Espaço ou A planta por 2 moedas.", 18, 60, "#3b2f6b", 16, "left");
    SZGame2D.drawSprite(ctx, canteiro1);
    SZGame2D.drawSprite(ctx, canteiro2);
    SZGame2D.drawSprite(ctx, canteiro3);
    SZGame2D.drawScore(ctx, "Moedas: ", moedas, 470, 100, "#3b2f6b", 18);
    SZGame2D.drawScore(ctx, "Canteiro: ", escolhido, 470, 126, "#3b2f6b", 18);
  }, "nuvens_quadro_1_loops_0");
}, "__sz-project");

